  add('gn',6,5,'Depravação universal','Todos os pensamentos do coração continuamente maus.',[I(T.ag,'Pecado original','A queda contaminou toda raça — não há justo.','«O coração é ídolo de si mesmo.»'),I(T.lu,'Depravação total','O homem está morto em pecado.','«O homem é incapaz de bem sem graça.»'),I(T.ca,'Total depravity','O pecado afeta cada faculdade.','«Não há saúde — completamente corrompido.»')]);
  add('gn',8,22,'Aliança com a criação','Dias e noites, verão e inverno não cessarão.',[I(T.ca,'Aliança de preservação','Deus preserva a ordem natural.','«Enquanto a terra existir, semente não cessará.»'),I(T.ba,'Aliança cósmica','A aliança com a criação é pré-condição.','«Deus se vincula à criação antes de exigir.»'),I(T.wi,'Renovação','A aliança aponta para restauração.','«Deus não destruirá — renovará pela ressurreição.»')]);
