  add('gn',28,15,'Promessa de presença','Deus promete estar com Jacó.',[I(T.ag,'Presença permanente','A presença é a maior promessa.','«Eis que eu estou contigo — maior promessa.»'),I(T.ca,'Aliança pessoal','Deus faz aliança com cada pessoa.','«Deus faz aliança com cada um.»'),I(T.st,'Companheirismo','A presença é fundamento da oração.','«Deus caminha conosco — não está distante.»')]);
