  add('ex',20,12,'Honrar pai e mãe','Primeiro mandamento com promessa.',[I(T.ag,'Ordem natural','A família é primeira escola de virtude.','«Honrar pais é honrar Deus.»'),I(T.lu,'Vocação','Vida cotidiana é vocação.','«Família é primeira vocação.»'),I(T.wi,'Reino de Deus','Honrar é viver o reino no lar.','«O reino começa em casa.»')]);
  add('ex',31,18,'Tábuas da Lei','Escritas pelo dedo de Deus.',[I(T.ag,'Lei e graça','A Lei é santa, mas revela sem curar.','«Lei dada para que pecado abundasse.»'),I(T.lu,'Lei e evangelho','Lei acusa, evangelho consola.','«Lei é espelho — evangelho é remédio.»'),I(T.ca,'Três usos','Conter mal, revelar pecado, guiar justo.','«Lei não abolida — cumprida em Cristo.»')]);
  // LÊVITICO
