  add('nm',21,8,'Serpente de bronze','Moisés faz serpente — quem olhar viverá.',[I(T.ag,'Tipologia','Serpente prefigura Cristo crucificado.','«Assim como serpente, Filho do homem será levantado.»'),I(T.lu,'Fé no visível','A fé se apega ao meio visível.','«Fé se apega ao meio que Deus oferece.»'),I(T.wi,'Cristologia','O que mata é levantado para curar.','«Paradoxo da cruz — o que mata cura.»')]);
