  add('dt',6,5,'Amarás o Senhor de todo coração','Mandamento supremo.',[I(T.ag,'Amor total','Amor sem divisão de lealdade.','«Ama Deus e faz — se amor perfeito, tudo seguirá.»'),I(T.ta,'Amor beatífico','O amor a Deus é fim último.','«Fim último é visão beatífica — ver Deus.»'),I(T.ca,'Adoração','Adoração é dever supremo.','«Adoração é dever — não apenas no templo.»')]);
