  add('dt',30,19,'Vida e morte','Escolhe a vida para que vivas.',[I(T.ag,'Liberdade','Deus respeita liberdade — escolha real.','«Deus respeita liberdade — escolha real.»'),I(T.lu,'Graça','A escolha é pela graça — Deus habilita.','«Escolha é pela graça — Deus habilita ao bem.»'),I(T.ca,'Soberania','Soberania e responsabilidade coexistem.','«Soberania e responsabilidade coexistem.»')]);
