  // 2 CRÔNICAS
  add('2cr',7,14,'Curar a terra','Se o povo se humilhar e orar.',[I(T.ag,'Conversão','A cura começa com conversão.','«Cura começa com humildade.»'),I(T.lu,'Arrependimento','O arrependimento é caminho.','«Sem mudança, não há cura.»'),I(T.sp,'Oração','Deus responde ao clamor humilde.','«Deus responde à oração humilde.»')]);
  // SALMOS
