  add('sl',23,1,'O Senhor é o meu pastor','Metáfora pastoral — provisão e proteção.',[I(T.ag,'Providência','Deus supre todas as necessidades.','«Deus supre — não faltará nada.»'),I(T.ca,'Guia','Deus guia por caminhos certos.','«Deus guia — pastoreia, não abandona.»'),I(T.sp,'Confiança','Pode não ter medo, mesmo na morte.','«Mesmo no vale, estou seguro.»')]);
  add('sl',27,4,'Uma coisa peço ao Senhor','Habitar na casa do Senhor.',[I(T.ag,'Deseiro','Um desejo supremo — ver Deus.','«Desejo supremo — ver Deus.»'),I(T.ta,'Visão beatífico','O fim é contemplar a Deus.','«Um desejo — ver Deus.»'),I(T.wi,'Prioridade','A fé é sobre prioridades.','«Uma coisa — Deus primeiro.»')]);
