  add('sl',51,7,'Lava-me e ficarei mais branco','Purificação divina — misericórdia soberana.',[I(T.ag,'Misericórdia','Misericórdia superior a sacrifícios.','«Misericórdia — Deus não deseja sacrifício.»'),I(T.ca,'Graça','A graça transforma — lava, purifica.','«Graça lava — faz branco.»'),I(T.le,'Humildade','Humildade é reconhecer a necessidade.','«Humildade — saber que Deus lava.»')]);
  add('sl',73,26,'Meu coração e minha carne languidem','Dúvida resolvida pela presença de Deus.',[I(T.ag,'Presença','A presença de Deus sustenta.','«Deus é a porção — sem Ele, nada.»'),I(T.ca,'Fé crida','A fé não é sentimento — é escolha.','«Fé não é sentimento — é escolha.»'),I(T.wi,'Provação','O salmoist duvidou mas Deus provou.','«Dúvida existe — mas Deus se revela.»')]);
