  add('sl',119,105,'Lâmpada para meus pés','A palavra guia a vida do crente.',[I(T.ag,'Iluminação','A palavra é luz — não permite tropeço.','«Palavra é luz — guia passos.»'),I(T.lu,'Autoridade','A palavra é autoridade máxima.','«Palavra é autoridade — não é letra.»'),I(T.st,'Prática','A Palavra é guia diária.','«Palavra é guia prática — caminhar nela.»')]);
